        "key_moments": [
          {
            "start_seconds": 13.0,
            "end_seconds": 50.0,
            "timestamp_display": "00:13 - 00:50",
            "title": "Team survival advantages and risk distribution",
            "yield_score": 9,
            "why_essential": "Team startups outperform solo founders on survival, scale, and resilience by distributing risk, skills, capital, and judgment, preventing single points of failure.",
            "key_takeaway": "Teams provide critical resilience and diverse perspectives, but only if they function effectively; a bad team is worse than a good solo founder."
          },
          {
            "start_seconds": 50.0,
            "end_seconds": 110.0,
            "timestamp_display": "00:50 - 01:50",
            "title": "The double-edged sword of homophily in co-founding",
            "yield_score": 8,
            "why_essential": "Founders tend to pick co-founders similar to themselves (homophily), which creates comfort and trust but compresses networks and risks overlapping blind spots, potentially leaving critical skill gaps unaddressed.",
            "key_takeaway": "Homophily optimizes for comfort, not complementary skill; relying solely on familiarity can undermine startup stability under pressure."
          },
          {
            "start_seconds": 110.0,
            "end_seconds": 170.0,
            "timestamp_display": "01:50 - 02:50",
            "title": "Trust vs. complementarity in founding teams",
            "yield_score": 10,
            "why_essential": "High trust and high homophily can create a structural blind spot where trust does not automatically extend to new team members, leading to feelings of unfairness and cheating when skill-based hires are brought in later.",
            "key_takeaway": "Trust and complementarity are distinct; a team can have high trust but zero complementarity, or vice versa, and both must be deliberately assessed."
          },
          {
            "start_seconds": 170.0,
            "end_seconds": 230.0,
            "timestamp_display": "02:50 - 03:50",
            "title": "The friendship trap in co-founding teams",
            "yield_score": 7,
            "why_essential": "Teams of friends have higher co-founder turnover than teams of strangers because comfort inhibits the blunt conversations needed to resolve conflict, and friends are more reluctant to address the 'elephant in the room'.",
            "key_takeaway": "Existing comfort does not protect a partnership; clear agreements on roles and conflict resolution must happen before starting, not during pressure."
          },
          {
            "start_seconds": 230.0,
            "end_seconds": 290.0,
            "timestamp_display": "03:50 - 04:50",
            "title": "Deliberate co-founder selection criteria",
            "yield_score": 9,
            "why_essential": "The critical question is not just 'do I trust this person?' but 'would I have chosen to work with them on this problem if I didn't already trust them?' Deliberate selection should focus on skill gaps and mission alignment, not just familiarity.",
            "key_takeaway": "Evaluate co-founders based on complementary skills and aligned mission, not just pre-existing trust or friendship."
          }
        ]
